#include <vector>
#include <numeric>
using namespace std;

class Solution {
public:
    /**
     * 方法一：數學求和
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    int missingNumber(vector<int>& nums) {
        int n = nums.size();
        int expected_sum = n * (n + 1) / 2;
        int actual_sum = accumulate(nums.begin(), nums.end(), 0);
        return expected_sum - actual_sum;
    }

    /**
     * 方法二：XOR 位元運算
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    int missingNumber_xor(vector<int>& nums) {
        int result = nums.size();

        for (int i = 0; i < nums.size(); i++) {
            result ^= i ^ nums[i];
        }

        return result;
    }
};

