class Solution {
    /**
     * 方法一：數學求和
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    public int missingNumber(int[] nums) {
        int n = nums.length;
        int expectedSum = n * (n + 1) / 2;
        int actualSum = 0;

        for (int num : nums) {
            actualSum += num;
        }

        return expectedSum - actualSum;
    }

    /**
     * 方法二：XOR 位元運算
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    public int missingNumber_xor(int[] nums) {
        int result = nums.length;

        for (int i = 0; i < nums.length; i++) {
            result ^= i ^ nums[i];
        }

        return result;
    }
}

